// Geometry and palette of the Real Good AI bulb (the logo's glass, filled like a liquid).
// Shared by <rg-bulb>, the copy-paste embed snippet and the stream overlay.
//
// The width samples describe the glass from the top of the dome (y = 323.59) down to the
// glass/socket seam (y = 736.47), sampled numerically off the logo's own bezier curves. Since the
// bulb is a flat silhouette, the area under the curve is just width(y) dy, so narrow parts (the
// neck, the apex) fill faster than the wide shoulder.
//
// The functions below that end up inside the embed snippet (createBulbGeometry, calculateLap,
// paletteColorOf) are written WITHOUT free variables on purpose: the snippet embeds their own
// source text (Function.prototype.toString), so there is a single copy of the maths.

export interface WidthSample {
  /** Offset from the top of the glass, in SVG units. */
  o: number;
  /** Width of the glass at that offset. */
  w: number;
}

export interface BulbColors {
  /** The front wave and the liquid. */
  a: string;
  /** The back wave. */
  b: string;
}

