export interface BulbGeometry {
  /** SVG y of the liquid surface when the glass is `fraction` (0..1) full by area. */
  liquidSurfaceY(fraction: number): number;
}

/** Builds the fill-level lookup from width samples. No free variables (see the note at the top). */
export function createBulbGeometry(
  samples: readonly WidthSample[],
  glassTop: number,
  glassBottom: number,
): BulbGeometry {
  const SAMPLE_COUNT = 300;
  const glassHeight = glassBottom - glassTop;

  function widthAt(offset: number): number {
    for (let i = 0; i < samples.length - 1; i++) {
      const a = samples[i];
      const b = samples[i + 1];
      if (offset >= a.o && offset <= b.o) {
        const t = (offset - a.o) / (b.o - a.o);
        return a.w + t * (b.w - a.w);
      }
    }
    return samples[samples.length - 1].w;
  }

  // Cumulative area from the top, normalized to 0..1.
  const cumulative = [0];
  for (let i = 1; i <= SAMPLE_COUNT; i++) {
    cumulative.push(cumulative[i - 1] + widthAt((glassHeight * i) / SAMPLE_COUNT));
  }
  const total = cumulative[cumulative.length - 1];
  for (let j = 0; j < cumulative.length; j++) cumulative[j] = cumulative[j] / total;

  return {
    liquidSurfaceY(fraction: number): number {
      fraction = Math.max(0, Math.min(1, fraction));
      for (let i = SAMPLE_COUNT; i >= 1; i--) {
        const areaFromBottom = 1 - cumulative[i - 1];
        if (areaFromBottom >= fraction) {
          const areaPrev = 1 - cumulative[i];
          const t = (fraction - areaPrev) / (areaFromBottom - areaPrev || 1);
          const offPrev = (glassHeight * (i - 1)) / SAMPLE_COUNT;
          const offCur = (glassHeight * i) / SAMPLE_COUNT;
          return glassTop + offPrev + t * (offCur - offPrev);
        }
      }
      return glassTop;
    },
  };
}

/**
 * Laps: once a campaign raises more than its goal, the bulb fills, changes color and starts
 * again at the fraction of the next goal-multiple raised. No free variables.
 */
export function calculateLap(raised: number, goal: number): { lap: number; fraction: number } {
  if (!goal || goal <= 0) return { lap: 0, fraction: 0 };
  const lap = Math.floor(raised / goal);
  return { lap, fraction: (raised - lap * goal) / goal };
}

/** The palette entry of a lap (cycling, safe for negative indexes). No free variables. */
export function paletteColorOf(palette: readonly BulbColors[], index: number): BulbColors {
  return palette[((index % palette.length) + palette.length) % palette.length];
}
